<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Database/Connection.php';
$date=$argv[1]??gmdate('Y-m-d');$db=$argv[2]??dirname(__DIR__).'/database/forecast.sqlite';$pdo=MarketForecast\Database\Connection::open($db);
$q=$pdo->prepare("SELECT COUNT(*) n,SUM(CASE WHEN er.id IS NOT NULL THEN 1 ELSE 0 END) resolved,SUM(CASE WHEN er.direction_correct=1 THEN 1 ELSE 0 END) correct,AVG(er.absolute_error_pct) mae FROM final_predictions fp LEFT JOIN evaluation_results er ON er.final_prediction_id=fp.id WHERE substr(fp.generated_at,1,10)=?");$q->execute([$date]);$r=$q->fetch(PDO::FETCH_ASSOC)?:['n'=>0,'resolved'=>0,'correct'=>0,'mae'=>null];$resolved=(int)$r['resolved'];$s=$pdo->prepare('INSERT INTO daily_aggregates(aggregate_date,forecast_count,resolved_count,correct_count,accuracy,mean_absolute_error,created_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(aggregate_date) DO UPDATE SET forecast_count=excluded.forecast_count,resolved_count=excluded.resolved_count,correct_count=excluded.correct_count,accuracy=excluded.accuracy,mean_absolute_error=excluded.mean_absolute_error,created_at=excluded.created_at');$now=gmdate('c');$s->execute([$date,(int)$r['n'],$resolved,(int)$r['correct'],$resolved?((int)$r['correct']/$resolved):null,$r['mae'],$now]);echo json_encode(['date'=>$date,'forecast_count'=>(int)$r['n'],'resolved_count'=>$resolved],JSON_THROW_ON_ERROR),PHP_EOL;
